arguments.command:
python3 -c "
from openpyxl import load_workbook
wb = load_workbook('budget.xlsx')
ws = wb.active
print('dims:', ws.dimensions, 'max_row', ws.max_row, 'max_col', ws.max_column)
for row in ws.iter_rows():
    for c in row:
        if c.value is not None:
            print(c.coordinate, repr(c.value), 'numfmt=', c.number_format, 'font=', c.font.color.rgb if c.font.color else None)
"
